<?php
if(PHP_SAPI!=='cli')exit;
require (dirname(__DIR__, 2) . '/app/Bootstrap/bootstrap.php');MarketplaceModule::boot();require_once (dirname(__DIR__, 2) . '/app/Modules/Marketplace/Services/MarketplaceShippingDocumentService.php');
